    if (bounds == null) {
        throw new IllegalArgumentException("Input list bounds cannot be null");
    }

    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    long currentSuffixSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        if (bounds.get(i) == null) {
            throw new IllegalArgumentException("Element in bounds list cannot be null");
        }
        totalSum += bounds.get(i);
        currentSuffixSum += bounds.get(i);
        suffixSum.add(0, (int) currentSuffixSum);
    }

