    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence at the end of string");
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'n':
                    output.append('\n');
