public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props cannot be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null; // or throw an exception, depending on how you want to handle missing keys
    }

    // Simple variable substitution logic assuming variables are in the form ${varName}
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        if (value.startsWith("${", i)) {
            int start = i + 2;
            int end = value.indexOf('}', start);
            if (end == -1) {
                throw new IllegalArgumentException("Invalid variable syntax: " + value.substring(i));
            }
            String varName = value.substring(start, end);
            String varValue = props.getProperty(varName);
            if (varValue == null) {
                throw new IllegalArgumentException("Undefined variable: " + varName);
            }
            result.append(varValue);
            i = end + 1;
        } else {
            result.append(value.charAt(i));
            i++;
        }
    }

    return result.toString();
}

