    }
    String name = buf.toString();
    if (nameStart >= name.length()) {
        throw new IllegalArgumentException("Start index is greater than the length of the buffer");
    }

    // Assuming abbreviation means taking the first character and the last name part after the last space
    int lastSpaceIndex = name.lastIndexOf(' ', nameStart);
    if (lastSpaceIndex == -1) {
        // No space found, abbreviate the whole string from nameStart
        buf.setLength(0);
        buf.append(name.charAt(nameStart)).append('.').append(name.substring(nameStart + 1));
    } else {
