public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.canRead()) {
        throw new IOException("Invalid or unreadable file provided.");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges list cannot be null or empty.");
    }

    List<ThreadSnapshot> allSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = parseLineToThreadSnapshot(line);
            if (snapshot != null && isSnapshotInTimeRanges(snapshot, timeRanges)) {
                allSnapshots.add(snapshot);
            }
        }
    }
    return allSnapshots;
}

private static ThreadSnapshot parseLineToThreadSnapshot(String line) {
    // Assuming each line is a valid ThreadSnapshot representation
    // This method should be implemented based on the actual file format
    // For now, let's assume a simple parsing logic
    String[] parts = line.split(",");
    if (parts.length < 3) {
        return null; // Invalid line format
    }
    try {
        long timestamp = Long.parseLong(parts[0]);
        String threadName = parts[1];
        String state = parts[2];
        return new ThreadSnapshot(timestamp, threadName, state);
    } catch (NumberFormatException e) {
        return null; // Invalid timestamp format
    }
}

private static boolean isSnapshotInTimeRanges(ThreadSnapshot snapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
    long snapshotTime = snapshot.getTimestamp();
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (snapshotTime >= range.getStartTime() && snapshotTime <= range.getEndTime()) {
            return true;
        }
    }
    return false;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("Invalid file: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges cannot be null or empty");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (snapshot.getTimestamp() >= range.getStartTime() && snapshot.getTimestamp() <= range.getEndTime()) {
                    snapshots.add(snapshot);
                    break;
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading file: " + file, e);
    }
    return snapshots;
}

