private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int index = 0;
    boolean inMethodArgs = false;
    while (index < descriptor.length()) {
        char currentChar = descriptor.charAt(index);

        if (currentChar == '(') {
            // Start of method arguments
            inMethodArgs = true;
            index++;
            continue;
        } else if (currentChar == ')') {
            // End of method arguments
            inMethodArgs = false;
            index++;
            continue;
        }

        if (inMethodArgs) {
            switch (currentChar) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                case 'L': // object reference
                    index = consumeFieldType(descriptor, index);
                    break;
                case '[': // array
                    index = consumeArrayType(descriptor, index);
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor character: " + currentChar);
            }
        }
        index++;
    }
}

private int consumeFieldType(final String descriptor, int index) {
    if (descriptor.charAt(index) == 'L') {
        while (descriptor.charAt(index) != ';') {
            index++;
        }
        index++; // consume the ';'
    }
    return index;
}

private int consumeArrayType(final String descriptor, int index) {
    while (descriptor.charAt(index) == '[') {
        index++;
    }
    return consumeFieldType(descriptor, index);
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor case
        index = 1; // Skip the '('
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index);
        }
        index++; // Skip the ')'
    }

    // Pop return type if it's not a void method
    if (descriptor.charAt(index) != 'V') {
        popType(descriptor, index);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': case 'C': case 'D': case 'F':
        case 'I': case 'J': case 'S': case 'Z':
            // These are all single slot types
            index++;
            break;
        case 'L':
            // Object type, skip until ';'
            index = descriptor.indexOf(';', index) + 1;
            if (index == 0) {
                throw new IllegalArgumentException("Malformed descriptor: missing ';'");
            }
            break;
