public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    int prime = desiredCapacity;
    while (!isPrime(prime)) {
        prime++;
    }

    if (desiredCapacity >= 1000) {
        int maxAllowed = (int) (desiredCapacity * 1.11);
        while (prime > maxAllowed) {
            prime--;
            while (!isPrime(prime)) {
                prime--;
            }
        }
    }

    return prime;
}

private static boolean isPrime(int num) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 == 0 || num % 3 == 0) return false;
    for (int i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0) return false;
    }
    return true;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 2) {
        return 2;
    }

    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;

    while (!isPrime(candidate)) {
        candidate += 2;
    }

    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        candidate = findClosePrime(desiredCapacity);
    }

    return candidate;
}

private static boolean isPrime(int number) {
    if (number <= 1) return false;
    if (number <= 3) return true;
    if (number % 2 == 0 || number % 3 == 0) return false;
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) return false;
    }
    return true;
}

private static int findClosePrime(int desiredCapacity) {
    int lowerBound = (int) (desiredCapacity * 0.89);
    int upperBound = (int) (desiredCapacity * 1.11);

    for (int i = desiredCapacity; i <= upperBound; i++) {
        if (isPrime(i)) {
            return i;
        }
    }

    for (int i = desiredCapacity - 1; i >= lowerBound; i--) {
        if (isPrime(i)) {
            return i;
        }
    }

    return nextPrime(upperBound + 1); // Fallback, should not reach here
}

